import { api } from './api';

// -------------------------------------------------------------
// Spoken interviewer
// -------------------------------------------------------------
// Plays Piper audio generated by the backend through whatever output device
// the operating system is using (speakers, headphones, Bluetooth…). If the
// server voice is unavailable, the browser's own speech synthesis reads the
// fallback text instead, so the interview never stalls on audio.
//
// speak() resolves when speaking has finished (or failed); it never rejects.

const urlCache = new Map(); // "interview:item" / "phrase:key" -> object URL
let current = null; // { audio, resolve }

function stopCurrent() {
  if (current) {
    current.audio?.pause();
    current.resolve?.();
    current = null;
  }
  if (typeof window !== 'undefined' && window.speechSynthesis) window.speechSynthesis.cancel();
}

export function stopSpeaking() {
  stopCurrent();
}

async function resolveUrl(source) {
  const key = source.phrase ? `phrase:${source.phrase}` : `${source.interviewId}:${source.item}`;
  if (!urlCache.has(key)) {
    const url = source.phrase
      ? await api.getPhraseUrl(source.phrase)
      : await api.getSpeechUrl(source.interviewId, source.item);
    urlCache.set(key, url);
  }
  return urlCache.get(key);
}

function playUrl(url) {
  return new Promise((resolve, reject) => {
    const audio = new Audio(url);
    current = { audio, resolve };
    audio.onended = () => { current = null; resolve(); };
    audio.onerror = () => { current = null; reject(new Error('Audio playback failed')); };
    audio.play().catch((error) => { current = null; reject(error); });
  });
}

// Browser fallback voice; prefers a natural English voice when available.
function speakWithBrowser(text) {
  const synth = typeof window !== 'undefined' ? window.speechSynthesis : null;
  if (!synth || !text || typeof SpeechSynthesisUtterance === 'undefined') return Promise.resolve();
  return new Promise((resolve) => {
    const utterance = new SpeechSynthesisUtterance(text);
    const voices = synth.getVoices();
    utterance.voice = voices.find((v) => /natural|neural|google us english/i.test(v.name) && v.lang.startsWith('en'))
      || voices.find((v) => v.lang.startsWith('en')) || null;
    utterance.rate = 0.98;
    utterance.onend = () => resolve();
    utterance.onerror = () => resolve();
    current = { audio: null, resolve };
    synth.speak(utterance);
  });
}

/**
 * Speak an interview item or a fixed phrase.
 * @param {{interviewId?: string, item?: string, phrase?: string}} source
 * @param {string} fallbackText  read by the browser voice if Piper fails
 */
export async function speak(source, fallbackText = '') {
  stopCurrent();
  try {
    const url = await resolveUrl(source);
    await playUrl(url);
  } catch {
    await speakWithBrowser(fallbackText);
  }
}

// Short rising two-note chime: "your turn to answer". Silent if Web Audio
// is unavailable.
export function playTurnChime() {
  try {
    const Context = window.AudioContext || window.webkitAudioContext;
    if (!Context) return;
    const context = new Context();
    [660, 880].forEach((frequency, index) => {
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      const start = context.currentTime + index * 0.12;
      oscillator.frequency.value = frequency;
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(0.12, start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.18);
      oscillator.connect(gain).connect(context.destination);
      oscillator.start(start);
      oscillator.stop(start + 0.2);
    });
    setTimeout(() => context.close(), 600);
  } catch {
    // A missing chime must never break the interview.
  }
}
